CREATE OR REPLACE FUNCTION NbProjets(p_numsal IN NUMBER) RETURN NUMBER
IS
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb
  FROM TRAVAILLESUR
  WHERE numsal = p_numsal;
  RETURN v_nb;
END;

CREATE OR REPLACE TRIGGER trig_check_division
BEFORE INSERT ON TRAVAILLESUR
FOR EACH ROW
DECLARE
  v_div_sal NUMBER;
  v_div_proj NUMBER;
BEGIN
  SELECT SE.codediv INTO v_div_sal
  FROM SALARIE S
  JOIN SERVICE SE ON SE.codeserv = S.codeserv
  WHERE S.numsal = :new.numsal;

  SELECT codediv INTO v_div_proj
  FROM PROJET
  WHERE numproj = :new.numproj;

  IF v_div_sal != v_div_proj THEN
    RAISE_APPLICATION_ERROR(-20040, 'Le projet n''appartient pas à la division du salarié');
  END IF;
END;

CREATE OR REPLACE PROCEDURE infoDivision(p_codediv IN NUMBER)
IS
BEGIN
  FOR p IN (SELECT numproj, nomproj FROM PROJET WHERE codediv = p_codediv) LOOP
    DBMS_OUTPUT.PUT_LINE('Projet ' || p.numproj || ' - ' || p.nomproj);
    FOR s IN (
      SELECT S.numsal, S.nomsal
      FROM SALARIE S
      JOIN TRAVAILLESUR T ON T.numsal = S.numsal
      WHERE T.numproj = p.numproj
    ) LOOP
      DBMS_OUTPUT.PUT_LINE('  - ' || s.numsal || ' ' || s.nomsal);
    END LOOP;
  END LOOP;
END;
